hints:
def move_to_front(songs, title):
    result = songs.copy()
    if title in result:
        result.remove(title)
        result.insert(0, title)
    return result


def add_unique(songs, title):
    if title not in songs:
        songs.append(title)

steps.solution:
def move_to_front(songs, title):
    result = songs.copy()
    if title in result:
        result.remove(title)
        result.insert(0, title)
    return result


def add_unique(songs, title):
    if title not in songs:
        songs.append(title)
